public static void main(String[] args) {
    try (Scanner sc = new Scanner(System.in)) {
        int N = sc.nextInt();
        int M = sc.nextInt();

        ArrayList<Integer> listA = new ArrayList<>();
        ArrayList<Integer> listB = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            listA.add(sc.nextInt());
        }

        for (int i = 0; i < M; i++) {
            listB.add(sc.nextInt());
        }

        ArrayList<Integer> combinedList = new ArrayList<>(listA);
        combinedList.addAll(listB);

        Collections.sort(combinedList);

        boolean found = false;
        for (int i = 0; i < combinedList.size() - 1; i++) {
            int first = combinedList.get(i);
            int second = combinedList.get(i + 1);
            int indexFirst = listA.indexOf(first);
            int indexSecond = listA.indexOf(second);
            if (indexFirst != -1 && indexSecond != -1 && Math.abs(indexFirst - indexSecond) == 1) {
                System.out.println("Yes");
                found = true;
                break;
            }
        }

        if (!found) {
            System.out.println("No");
        }
    }
}
